import type * as React from "react";

type IconProps = React.SVGProps<SVGSVGElement>;
export const ChevronLeftIcon = (props: IconProps) => <svg data-icon="left" {...props} />;
export const ChevronRightIcon = (props: IconProps) => <svg data-icon="right" {...props} />;
export const ChevronDownIcon = (props: IconProps) => <svg data-icon="down" {...props} />;
